import type { ReactNode } from "react";
import { ThemeProvider } from "@qingye/ui/components/theme-provider";
import { UILocaleProvider } from "@qingye/ui/locale";

/** Include one documented CSS path in the app entry. */
export function QingyeProvider({ children }: { children: ReactNode }) {
  return <ThemeProvider><UILocaleProvider>{children}</UILocaleProvider></ThemeProvider>;
}
